getFixedRouteSlices = (route, node) => {
    const bounds = fie(node);
    const slices = [];
    for (let segmentIndex = 0; segmentIndex < route.route.length - 1; segmentIndex++) {
        const clippedSegment = bie(route.route[segmentIndex], route.route[segmentIndex + 1], bounds);
        if (!clippedSegment)
            continue;
        const end = {
            segmentIndex,
            point: clippedSegment.end,
        };
        const previous = slices.at(-1);
        if (previous &&
            previous.end.segmentIndex === segmentIndex - 1 &&
            yie(route.route[segmentIndex], bounds)) {
            previous.end = end;
        }
        else {
            slices.push({
                sourceRoute: route,
                start: { segmentIndex, point: clippedSegment.start },
                end,
            });
        }
    }
    return slices;
},

finishRegionalFallback() {
        if (!this.activeFallbackSolver)
            return;
        if (!this.activeNode) {
            throw new Error("Pipeline9 cannot finish a regional fallback without an active node");
        }
        this.recordRegionalCandidateRejections();
        const newRoutes = [];
        const replacementRoutesByConnectionName = new Map();
        for (const route of this.activeFallbackSolver.getOutput()) {
            if (!this.activeFallbackFixedRouteSections.has(route.connectionName)) {
                newRoutes.push(route);
                continue;
            }
            const replacementRoutes = replacementRoutesByConnectionName.get(route.connectionName) ?? [];
            replacementRoutes.push(route);
            replacementRoutesByConnectionName.set(route.connectionName, replacementRoutes);
        }
        const pendingFixedRouteReplacements = [];
        const unchangedFixedRouteSections = [];
        for (const [connectionName, section] of this
            .activeFallbackFixedRouteSections) {
            const replacementRoutes = replacementRoutesByConnectionName.get(connectionName) ?? [];
            if (replacementRoutes.length === 0) {
                unchangedFixedRouteSections.push(section);
                continue;
            }
            if (replacementRoutes.length > 1) {
                this.error = `Pipeline9 regional fallback expected one replacement for fixed route "${connectionName}", got ${replacementRoutes.length}`;
                this.failed = true;
                return;
            }
            const splicedRoute = Pie({
                section,
                replacement: replacementRoutes[0],
                sourceMutationMasks: this.preloadedTraceMutationMasks,
                replacementIsMutated: true,
            });
            pendingFixedRouteReplacements.push({
                connectionName,
                section,
                replacement: splicedRoute.route,
                mutatedSegments: splicedRoute.mutatedSegments,
                replacementProducedSegment: splicedRoute.replacementProducedSegment,
            });
        }
        const candidateRoutes = [
            ...newRoutes,
            ...pendingFixedRouteReplacements.map(({ replacement }) => replacement),
        ];
        const fixedObstacleRoutes = [
            ...this.activeFallbackFixedObstacleRoutes,
            ...unchangedFixedRouteSections.flatMap((section) => section.sourceRoutes),
        ];
        const candidateBounds = Cre(this.activeNode, this.obstacleMargin + Math.max(this.traceWidth, this.viaDiameter) / 2);
        const conflictingFixedRoutesByConnectionName = new Map();
        for (const candidateRoute of candidateRoutes) {
            for (const fixedRoute of fixedObstacleRoutes) {
                if (fs(candidateRoute, fixedRoute, this.connMap)) {
                    continue;
                }
                if (_s({
                    left: candidateRoute,
                    right: fixedRoute,
                    clearance: this.obstacleMargin,
                    leftBounds: candidateBounds,
                    layerCount: this.layerCount,
                    allowBlindAndBuriedVias: this.allowBlindAndBuriedVias,
                })) {
                    conflictingFixedRoutesByConnectionName.set(fixedRoute.connectionName, fixedRoute);
                }
            }
        }
        if (conflictingFixedRoutesByConnectionName.size > 0) {
            const conflictingConnectionNames = [
                ...conflictingFixedRoutesByConnectionName.keys(),
            ];
            const reconstructableConnectionNames = [
                ...conflictingFixedRoutesByConnectionName,
            ]
                .filter(([, fixedRoute]) => fixedRoute.isFixed !== true &&
                fixedRoute.isThroughObstacle !== true)
                .map(([connectionName]) => connectionName);
            const promotedConnectionNames = new Set(this.activeFallbackPromotedFixedRouteConnectionNames);
            for (const connectionName of reconstructableConnectionNames) {
                promotedConnectionNames.add(connectionName);
            }
            if (promotedConnectionNames.size ===
                this.activeFallbackPromotedFixedRouteConnectionNames.size) {
                const immutableThroughObstacleConnectionNames = [
                    ...conflictingFixedRoutesByConnectionName,
                ].flatMap(([connectionName, fixedRoute]) => fixedRoute.isThroughObstacle === true ? [connectionName] : []);
                this.error =
                    immutableThroughObstacleConnectionNames.length > 0
                        ? `Pipeline9 regional fallback conflicts with immutable through-obstacle route(s): ${immutableThroughObstacleConnectionNames.join(", ")}`
                        : `Pipeline9 promoted regional fallback could not resolve immutable fixed route conflict(s): ${conflictingConnectionNames.join(", ")}`;
                this.failed = true;
                return;
            }
            this.startRegionalFallback(promotedConnectionNames);
            return;
        }
        const mutationRangeByTraceIndex = new Map();
        for (const { section, replacementProducedSegment, } of pendingFixedRouteReplacements) {
            if (!replacementProducedSegment)
                continue;
            for (const sourceRoute of section.sourceRoutes) {
                const routePositionStart = sourceRoute.preloadedRoutePositionStart;
                const routePositionEnd = sourceRoute.preloadedRoutePositionEnd;
                if ((routePositionStart === undefined) !==
                    (routePositionEnd === undefined)) {
                    throw new Error(`Pipeline9 fixed route "${sourceRoute.connectionName}" has incomplete route-position metadata`);
                }
                const rangeStart = Math.min(routePositionStart ?? sourceRoute.preloadedRouteIndex, routePositionEnd ?? sourceRoute.preloadedRouteIndex);
                const rangeEnd = Math.max(routePositionStart ?? sourceRoute.preloadedRouteIndex, routePositionEnd ?? sourceRoute.preloadedRouteIndex);
                const existingRange = mutationRangeByTraceIndex.get(sourceRoute.preloadedTraceIndex);
                mutationRangeByTraceIndex.set(sourceRoute.preloadedTraceIndex, {
                    start: Math.min(existingRange?.start ?? rangeStart, rangeStart),
                    end: Math.max(existingRange?.end ?? rangeEnd, rangeEnd),
                });
            }
        }
        for (const { connectionName, section, replacement, mutatedSegments, } of pendingFixedRouteReplacements) {
            this.fixedRouteReplacements.set(connectionName, replacement);
            this.preloadedTraceMutationMasks.set(connectionName, mutatedSegments);
            for (const sourceRoute of section.sourceRoutes.slice(1)) {
                this.removedFixedRouteConnectionNames.add(sourceRoute.connectionName);
                this.preloadedTraceMutationMasks.delete(sourceRoute.connectionName);
            }
        }
        const postSpliceNode = this.activeFallbackSolver.params.nodeWithPortPoints;
        const postSpliceSlices = this.getUpdatedFixedHdRoutes()
            .filter((route) => route.isFixed !== true && route.isThroughObstacle !== true)
            .flatMap((route) => getFixedRouteSlices(route, postSpliceNode));
        const markedTraceIndexes = new Set();
        for (const slice of postSpliceSlices) {
            if (slice.start.point.z === slice.end.point.z &&
                Math.hypot(slice.start.point.x - slice.end.point.x, slice.start.point.y - slice.end.point.y) <= Ia) {
                continue;
            }
            const sourceRoute = slice.sourceRoute;
            const mutationRange = mutationRangeByTraceIndex.get(sourceRoute.preloadedTraceIndex);
            if (!mutationRange)
                continue;
            const start = sourceRoute.preloadedRoutePositionStart ??
                sourceRoute.preloadedRouteIndex;
            const end = sourceRoute.preloadedRoutePositionEnd ??
                sourceRoute.preloadedRouteIndex;
            const sourceRange = {
                start: Math.min(start, end),
                end: Math.max(start, end),
            };
            const sourceIsPoint = sourceRange.start === sourceRange.end;
            const mutationIsPoint = mutationRange.start === mutationRange.end;
            const overlapsMutation = sourceIsPoint || mutationIsPoint
                ? sourceRange.start <= mutationRange.end &&
                    mutationRange.start <= sourceRange.end
                : sourceRange.start < mutationRange.end &&
                    mutationRange.start < sourceRange.end;
            if (!overlapsMutation)
                continue;
            markedTraceIndexes.add(sourceRoute.preloadedTraceIndex);
            const mask = [
                ...(this.preloadedTraceMutationMasks.get(sourceRoute.connectionName) ?? Array(sourceRoute.route.length - 1).fill(false)),
            ];
            if (mask.length !== sourceRoute.route.length - 1) {
                throw new Error(`Pipeline9 fixed route mutation mask for "${sourceRoute.connectionName}" has ${mask.length} segments, expected ${sourceRoute.route.length - 1}`);
            }
            for (let segmentIndex = slice.start.segmentIndex; segmentIndex <= slice.end.segmentIndex; segmentIndex++) {
                mask[segmentIndex] = true;
            }
            this.preloadedTraceMutationMasks.set(sourceRoute.connectionName, mask);
        }
        for (const preloadedTraceIndex of mutationRangeByTraceIndex.keys()) {
            if (!markedTraceIndexes.has(preloadedTraceIndex)) {
                throw new Error(`Pipeline9 could not capture accepted mutation provenance for trace ${preloadedTraceIndex}`);
            }
        }
        const reroutedFixedRouteCount = pendingFixedRouteReplacements.reduce((count, { section }) => count + section.sourceRoutes.length, 0);
        this.stats.reroutedFixedRouteCount =
            Number(this.stats.reroutedFixedRouteCount ?? 0) + reroutedFixedRouteCount;
        this.stats.reroutedFixedRouteSectionCount =
            Number(this.stats.reroutedFixedRouteSectionCount ?? 0) +
                pendingFixedRouteReplacements.length;
        this.finishActiveNode(newRoutes);
    }
